// src/pages/LoginRequiredPage.tsx
import React, { useState } from "react";
import { useNavigate } from "react-router-dom";

export default function LoginRequiredPage() {
  const nav = useNavigate();
  const [q, setQ] = useState("");

  const onSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!q.trim()) return;
    nav(`/search?q=${encodeURIComponent(q.trim())}`);
  };

  return (
    // 좌우/상하가 까만 여백으로 채워지고, 중앙에 패널만 보이도록
    <div className="min-h-screen bg-grey grid place-items-start">
      <div className="mx-auto h-full w-full max-w-[480px]">
        <div className="l">

          {/* 검색 인풋 (스샷처럼 밑줄만 보이는 스타일) */}
          <main className="px-6 pt-6">
            <form onSubmit={onSubmit}>
              <div className="relative">
                <input
                  value={q}
                  onChange={(e) => setQ(e.target.value)}
                  placeholder="검색하세요"
                  className="
                    block w-full
                    text-[24px] md:text-[24px]
                    placeholder:text-gray-400
                    outline-none
                    border-0
                    border-b border-gray-400
                    pb-2
                    focus:border-black
                    transition
                  "
                  aria-label="검색어 입력"
                />
                {/* 우측 돋보기(클릭으로도 제출) */}
                <button
                  type="submit"
                  aria-label="검색"
                  className="absolute right-0 bottom-1 h-10 w-10 grid place-items-center rounded-full hover:bg-black/5 active:scale-95 transition"
                >
                  <svg width="22" height="22" viewBox="0 0 24 24" stroke="currentColor" fill="none">
                    <circle cx="11" cy="11" r="7" strokeWidth="2" />
                    <path d="M20 20l-3-3" strokeWidth="2" strokeLinecap="round" />
                  </svg>
                </button>
              </div>
            </form>
          </main>
        </div>
      </div>
    </div>
  );
}
